/**
 * Real image bytes for the gates: a PNG built here (any size, with or without
 * alpha) and a real 3×2 JPEG (made by macOS sips), which can be given an EXIF
 * orientation. Shared by verify-rules, verify-pdf and verify-a11y-app.
 */
import { crc32, deflateSync } from 'node:zlib';

const chunk = (type, data) => {
  const length = Buffer.alloc(4);
  length.writeUInt32BE(data.length);
  const body = Buffer.concat([Buffer.from(type, 'latin1'), data]);
  const crc = Buffer.alloc(4);
  crc.writeUInt32BE(crc32(body));
  return Buffer.concat([length, body, crc]);
};

/** A `width`×`height` PNG, RGB or RGBA, in a gradient so it isn't blank. */
export function png(width, height, { alpha = false } = {}) {
  const ihdr = Buffer.alloc(13);
  ihdr.writeUInt32BE(width, 0);
  ihdr.writeUInt32BE(height, 4);
  ihdr[8] = 8;
  ihdr[9] = alpha ? 6 : 2;
  const raw = [];
  for (let y = 0; y < height; y++) {
    raw.push(0);
    for (let x = 0; x < width; x++) raw.push(200, (40 * x) % 256, (60 * y) % 256, ...(alpha ? [x % 2 ? 255 : 128] : []));
  }
  return new Uint8Array(Buffer.concat([
    Buffer.from([0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a]),
    chunk('IHDR', ihdr),
    chunk('IDAT', deflateSync(Buffer.from(raw))),
    chunk('IEND', Buffer.alloc(0)),
  ]));
}

/** A real 3×2 baseline JPEG, three channels, no orientation tag. */
export const JPEG_3X2 = new Uint8Array(Buffer.from('', 'base64'));

/** `jpeg` with an EXIF block giving `orientation` (1–8), right after its SOI. */
export function withOrientation(jpeg, orientation) {
  const exif = Buffer.from([
    0xff, 0xe1, 0x00, 0x22, // APP1, length 34
    0x45, 0x78, 0x69, 0x66, 0x00, 0x00, // "Exif\0\0"
    0x4d, 0x4d, 0x00, 0x2a, 0x00, 0x00, 0x00, 0x08, // big-endian TIFF, IFD0 at 8
    0x00, 0x01, // one entry
    0x01, 0x12, 0x00, 0x03, 0x00, 0x00, 0x00, 0x01, 0x00, orientation, 0x00, 0x00, // Orientation, SHORT, 1
    0x00, 0x00, 0x00, 0x00, // no next IFD
  ]);
  return new Uint8Array(Buffer.concat([Buffer.from(jpeg.subarray(0, 2)), exif, Buffer.from(jpeg.subarray(2))]));
}
